      document.body.appendChild(d);d.showModal();this.F.setFilterBackend(new this.F.Canvas2dFilterBackend());this.canvas=new this.F.Canvas(this.q('[data-canvas]'),{width:this.board.width,height:this.board.height,preserveObjectStacking:true,selection:true,backgroundColor:'#fffaf2',enableRetinaScaling:true,uniformScaling:true});
