    markDirty(){this.dirty=true;this.q('[data-save-state]').textContent='Unsaved changes';this.q('[data-save-state]').classList.add('bae-dirty');this.syncButtons();}
    syncButtons(){if(!this.dialog)return;for(const a of ['save','export-panel','close'])this.q('[data-action="'+a+'"]').disabled=this.busy;this.q('[data-action=undo]').disabled=this.busy||this.historyIndex<=0;this.q('[data-action=redo]').disabled=this.busy||this.historyIndex>=this.history.length-1;this.q('[data-board]').disabled=this.busy;this.q('[data-device]').disabled=this.busy;this.q('[data-layer-count]').textContent=(this.canvas?.getObjects().length||0)+' layers';}
